using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app", Name = "App Configuration",
        MimeType = "application/json")]
    [Description("Returns the current application configuration as JSON")]
    public static string GetAppConfig()
    {
        var config = new
        {
            Environment = "Production",
            Version = "1.0.0",
            Features = new { DarkMode = true, BetaAccess = false },
            MaxConnections = 100
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Check whether a specific feature flag is enabled")]
    public static string CheckFeatureFlag(
        [Description("Name of the feature flag to check (e.g., 'DarkMode', 'BetaAccess')")] string flagName)
    {
        var flags = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase)
        {
            ["DarkMode"] = true,
            ["BetaAccess"] = false,
            ["Notifications"] = true
        };

        if (flags.TryGetValue(flagName, out var enabled))
            return $"Feature '{flagName}' is {(enabled ? "enabled" : "disabled")}.";

        return $"Feature '{flagName}' not found. Available: {string.Join(", ", flags.Keys)}";
    }

    [McpServerTool, Description("Get the current server status and uptime")]
    public static string GetServerStatus()
    {
        return $"Server is running. Started at: {DateTime.UtcNow:O}. Status: Healthy.";
    }
}

